import {hypot2} from '../../lib/hypot2.ts';
/** Native trajectory observations, separate from the frozen musical judge.
 * Stored velocity is pre-solve. The next stored velocity minus gravity is the
 * current effective velocity; the final sample can use the already-read state.
 * No contact gate: internal motion can follow the final collision by a frame. */
import type {RawFrame, Vec2} from '../../lib/detector.ts';

export const MOTION_OBSERVATION_VERSION='line.motion-observation.v1';
export const NATIVE_GRAVITY=.175;
const speed=(v:Vec2)=>hypot2(v.x,v.y);
const direction=(a:Vec2,b:Vec2)=>Math.abs(Math.atan2(a.x*b.y-a.y*b.x,a.x*b.x+a.y*b.y));
const BODY_POINT_IDS=['BUTT','SHOULDER','RHAND','LHAND','LFOOT','RFOOT'] as const;
export type MotionSample={frame:number;incoming:Vec2;effective:Vec2;speedBefore:number;speedAfter:number;
  gravityGain:number;solverGain:number;directionCorrection:number};
type MotionFrames=readonly Pick<RawFrame,'frame'|'velocity'>[];

/** One observation algorithm serves both detailed reports and streaming totals. */
function visitMotion(frames:MotionFrames,from:number,to:number,terminalEffective:Vec2|undefined,visit:(sample:MotionSample)=>void):void{
  if(!Number.isSafeInteger(from)||!Number.isSafeInteger(to)||from<1||to<from)throw new Error('invalid motion observation window');
  const first=frames[0]?.frame,last=frames.at(-1)?.frame;
  if(first===undefined||last===undefined||from<first||to>last||to===last&&!terminalEffective)throw new Error('motion window requires its next velocity or terminal effective state');
  let previousSpeed:number|undefined;
  for(let frame=from;frame<=to;frame++){
    const row=frames[frame-first],next=frames[frame-first+1];
    if(row?.frame!==frame||next&&next.frame!==frame+1)throw new Error('motion samples require a contiguous native trajectory');
    const incoming=row.velocity,effective=next?{x:next.velocity.x,y:next.velocity.y-NATIVE_GRAVITY}:terminalEffective!;
    if(!Number.isFinite(incoming.x)||!Number.isFinite(incoming.y)||!Number.isFinite(effective.x)||!Number.isFinite(effective.y))throw new Error('nonfinite motion sample');
    const speedBefore=previousSpeed??hypot2(incoming.x,incoming.y-NATIVE_GRAVITY),speedAfter=speed(effective),incomingSpeed=speed(incoming);
    previousSpeed=speedAfter;
    visit({frame,incoming,effective,speedBefore,speedAfter,
      gravityGain:incomingSpeed-speedBefore,solverGain:speedAfter-incomingSpeed,
      directionCorrection:.5*(incomingSpeed+speedAfter)*direction(incoming,effective)});
  }
}
export function motionSamples(frames:MotionFrames,from:number,to:number,terminalEffective?:Vec2):MotionSample[]{
  const samples:MotionSample[]=[];
  visitMotion(frames,from,to,terminalEffective,sample=>samples.push(sample));
  return samples;
}

export type BurstBand={frames:number;absolute:number;relative:number};
/** Pilot bands anchored in the measured examples; not a universal beauty score.
 * Versioned separately so the calibration can be frozen with V6. */
export const MOTION_BANDS:readonly BurstBand[]=[
  {frames:1,absolute:.75,relative:.1},
  {frames:4,absolute:1.25,relative:.2},
  {frames:10,absolute:2,relative:.3},
];

/** A band needs only its rolling gain and the speed at the window's start. */
class BurstSummary {
  private readonly gains:number[];
  private readonly speeds:number[];
  private cursor=0;
  private count=0;
  private gain=0;
  private maximum=0;
  private maxRelative=0;
  private maxExcess=0;
  private excessIntegral=0;
  private peakFrame:number|null=null;
  private exceedanceFrames=0;
  private episodes=0;
  private last=-Infinity;
  constructor(private readonly band:BurstBand){
    this.gains=new Array(band.frames).fill(0);
    this.speeds=new Array(band.frames).fill(0);
  }
  add(sample:MotionSample):void{
    const {band,cursor}=this;
    this.gain+=sample.solverGain;
    if(this.count>=band.frames)this.gain-=this.gains[cursor];
    this.gains[cursor]=sample.solverGain;
    this.speeds[cursor]=sample.speedBefore;
    this.cursor=cursor+1===band.frames?0:cursor+1;
    if(++this.count<band.frames)return;
    const before=this.speeds[this.cursor],limit=Math.max(band.absolute,band.relative*before),excess=Math.max(0,this.gain-limit);
    this.maximum=Math.max(this.maximum,this.gain);
    this.maxRelative=Math.max(this.maxRelative,this.gain/Math.max(1,before));
    this.excessIntegral+=excess/band.frames;
    if(excess>this.maxExcess){this.maxExcess=excess;this.peakFrame=sample.frame;}
    if(excess>1e-9){this.exceedanceFrames++;if(sample.frame-this.last>band.frames)this.episodes++;this.last=sample.frame;}
  }
  result(){
    const {maximum,maxRelative,maxExcess,excessIntegral,peakFrame,exceedanceFrames,episodes}=this;
    return {...this.band,maximum,maxRelative,maxExcess,excessIntegral,peakFrame,exceedanceFrames,episodes};
  }
}
/** Interval bursts include preceding history; the passage totals stay local.
 * Detailed and streaming callers share these same accumulations. */
export class MotionSummary {
  private frames=0;
  private solverGain=0;
  private gravityGain=0;
  private positiveCorrection=0;
  private absoluteCorrection=0;
  private directionCorrection=0;
  private laterFrames=0;
  private laterAbsoluteCorrection=0;
  private laterDirectionCorrection=0;
  private readonly bursts:BurstSummary[];
  constructor(private readonly landingFrame:number,private readonly bands:readonly BurstBand[]=MOTION_BANDS,
    private readonly range?:{from:number;to:number}){
    this.bursts=bands.map(band=>new BurstSummary(band));
  }
  add(sample:MotionSample):void{
    const {range}=this;
    if(range&&sample.frame>range.to)return;
    for(let i=0;i<this.bursts.length;i++){
      if(!range||sample.frame>=range.from-this.bands[i].frames+1)this.bursts[i].add(sample);
    }
    if(range&&sample.frame<range.from)return;
    const absolute=Math.abs(sample.solverGain);
    this.frames++;
    this.solverGain+=sample.solverGain;this.gravityGain+=sample.gravityGain;
    this.positiveCorrection+=Math.max(0,sample.solverGain);this.absoluteCorrection+=absolute;
    this.directionCorrection+=sample.directionCorrection;
