      laterFrames,laterAbsoluteCorrection,laterDirectionCorrection}=this;
    return {schema:MOTION_OBSERVATION_VERSION,frames,bursts:this.bursts.map(burst=>burst.result()),
      solverGain,gravityGain,positiveCorrection,absoluteCorrection,directionCorrection,
      laterFrames,laterAbsoluteCorrection,laterDirectionCorrection};
  }
}
export function summarizeMotion(samples:readonly MotionSample[],landingFrame:number,bands:readonly BurstBand[]=MOTION_BANDS){
  const summary=new MotionSummary(landingFrame,bands);
  for(const sample of samples)summary.add(sample);
  return summary.result();
}

/** Compiler evaluation consumes each sample immediately instead of retaining
 * an array and then filtering it once for every burst band. */
export function summarizeMotionFrames(frames:MotionFrames,from:number,to:number,terminalEffective?:Vec2){
  const summary=new MotionSummary(from,MOTION_BANDS,{from,to});
  const first=Math.max(1,from-Math.max(...MOTION_BANDS.map(band=>band.frames))+1);
  visitMotion(frames,first,to,terminalEffective,sample=>summary.add(sample));
  return summary.result();
}
export function effectiveBodyVelocity(state:{points:Record<string,{x:number;y:number;prevX:number;prevY:number}>}):Vec2{
  let x=0,y=0;
  for(const id of BODY_POINT_IDS){
    const point=state.points[id];
    x+=(point.x-point.prevX)/BODY_POINT_IDS.length;
    y+=(point.y-point.prevY)/BODY_POINT_IDS.length;
  }
  return {x,y};
}

